           <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required fields</p>
         </div>

         <form id="support-form" novalidate>
           <div class="form-field">
             <label for="full-name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
             <input
               id="full-name"
