               type="email"
               autocomplete="email"
               required
               aria-describedby="email-error"
             >
             <p class="error-message" id="email-error" hidden>Error: Enter a valid email address, like name@example.com.</p>
           </div>

           <div class="form-field">
             <label for="phone">Phone number <span class="optional-text">(optional)</span></label>
             <input
               id="phone"
